package com.android.tools.lint.checks;

import com.android.tools.lint.detector.api.*;
import com.intellij.psi.PsiClass;
import com.intellij.psi.PsiClassType;
import com.intellij.psi.PsiField;
import com.intellij.psi.PsiModifier;
import com.intellij.psi.PsiType;
import com.intellij.psi.util.InheritanceUtil;
import com.intellij.psi.util.PsiTypesUtil;
import org.jetbrains.uast.UClass;
import org.jetbrains.uast.UElement;
import org.jetbrains.uast.UField;
import org.jetbrains.uast.visitor.UastVisitor;

import java.util.Collections;
import java.util.List;

public class ParcelDetector extends Detector implements Detector.SourceCodeScanner {

    public static final Issue ISSUE = Issue.create(
            "ParcelCreator",
            "Missing Parcelable CREATOR field",
            "Classes implementing the Parcelable interface must also have a static field called CREATOR, " +
            "which is an object implementing the Parcelable.Creator interface.",
            Category.CORRECTNESS,
            6,
            Severity.ERROR,
            new Implementation(ParcelDetector.class, Scope.JAVA_FILE_SCOPE));

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Collections.singletonList(UClass.class);
    }

    @Override
    public UElementHandler createUastHandler(@NotNull JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitClass(@NotNull UClass node) {
                if (node.isInterface() || node.hasModifierProperty(PsiModifier.ABSTRACT)) {
                    return;
                }
                PsiClass parcelable = context.getEvaluator().findClass("android.os.Parcelable");
                PsiClass cls = node.getJavaPsi();
                if (parcelable == null || cls == null || !cls.isValid() || !InheritanceUtil.isInheritor(cls, "android.os.Parcelable", true)) {
                    return;
                }
                // Check fields
                for (UField field : node.getFields()) {
                    if ("CREATOR".equals(field.getName()) && field.isStatic()) {
                        PsiType type = field.getType();
                        if (type instanceof PsiClassType) {
                            PsiClass fieldClass = ((PsiClassType) type).resolve();
                            if (fieldClass != null) {
                                PsiClass creatorClass = context.getEvaluator().findClass("android.os.Parcelable.Creator");
                                if (creatorClass != null && fieldClass.isEquivalentTo(creatorClass)) {
                                    return;
                                }
                            }
                        }
                    }
                }
                context.report(ISSUE, node, context.getNameLocation(node),
                    "This class implements android.os.Parcelable but does not define a static CREATOR field of type android.os.Parcelable.Creator");
            }
        };
    }
}
```

