public class ParcelDetector extends Detector implements SourceCodeScanner {
    private static final String PARCELABLE_CLS = "android.os.Parcelable";
    private static final String CREATOR_CLS = "android.os.Parcelable.Creator";

    public static final Issue ISSUE = Issue.create(
            "ParcelCreator",
            "Missing Parcelable `CREATOR` field",
            "...",
            Category.CORRECTNESS,
            6,
            Severity.ERROR,
            new Implementation(ParcelDetector.class, Scope.JAVA_FILE_SCOPE));

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Collections.singletonList(UClass.class);
    }

    @Override
    public UElementHandler createUastHandler(@NotNull JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitClass(@NotNull UClass node) {
                if (node.isInterface() || node.hasModifierProperty(PsiModifier.ABSTRACT)) {
                    return;
                }
                if (!context.getEvaluator().implementsInterface(node, PARCELABLE_CLS, false)) {
                    return;
                }
                for (UField field : node.getFields()) {
                    if ("CREATOR".equals(field.getName())
                            && field.hasModifierProperty(PsiModifier.STATIC)) {
                        PsiType type = field.getType();
                        if (type instanceof PsiClassType) {
                            PsiClass resolved = ((PsiClassType) type).resolve();
                            if (resolved != null
                                    && context.getEvaluator().implementsInterface(
                                            resolved, CREATOR_CLS, false)) {
                                return;
                            }
                        }
                    }
                }
                context.report(ISSUE, node, context.getNameLocation(node),
                        "This class implements android.os.Parcelable but does not define a "
                                + "static CREATOR field of type android.os.Parcelable.Creator");
            }
        };
    }
}
```

